import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Bare Metal Cloud OS Reinstallation Guide","description":"","frontmatter":{"title":"Bare Metal Cloud OS Reinstallation Guide"},"headers":[],"relativePath":"operations-knowledge-base/baremetal/bare-metal-cloud-os-reinstallation-guide.md","filePath":"operations-knowledge-base/baremetal/bare-metal-cloud-os-reinstallation-guide.md","lastUpdated":1794309341000}'),o={name:"operations-knowledge-base/baremetal/bare-metal-cloud-os-reinstallation-guide.md"};function s(r,e,l,d,h,p){return a(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document describes how to reinstall the operating system through the Bare Metal Cloud Control Panel, including operating system selection, login method configuration, data retention rules, and important considerations to help you complete the reinstallation successfully.</p><p><strong>Applicable Product:</strong> Bare Metal Cloud</p><hr><h2 id="_1-before-reinstalling-the-operating-system" tabindex="-1">1. Before Reinstalling the Operating System <a class="header-anchor" href="#_1-before-reinstalling-the-operating-system" aria-label="Permalink to &quot;1. Before Reinstalling the Operating System&quot;">​</a></h2><p>Before proceeding with OS reinstallation, please note the following:</p><ul><li>Reinstalling the operating system will reinstall the OS and <strong>format the system disk</strong>.</li><li>If your server has an additional <strong>data disk</strong>, <strong>only the system disk will be formatted</strong>. The data disk will <strong>not</strong> be formatted, and the data on it will be preserved.</li><li><strong>After the reinstallation is complete, the data disk will not be mounted automatically. You will need to mount it manually before accessing the data.</strong></li><li>Reinstalling the operating system will cause <strong>all existing snapshots of the instance to become invalid and be automatically deleted</strong>. Deleted snapshots cannot be recovered.</li><li>If a <strong>Custom Script</strong> was configured when the instance was created, it will be executed automatically during the OS reinstallation. Modifying or re-entering the script is not supported.</li><li>To prevent data loss, it is strongly recommended to back up all important data before proceeding.</li></ul><hr><h2 id="_2-how-to-reinstall-the-operating-system" tabindex="-1">2. How to Reinstall the Operating System <a class="header-anchor" href="#_2-how-to-reinstall-the-operating-system" aria-label="Permalink to &quot;2. How to Reinstall the Operating System&quot;">​</a></h2><ol><li>Log in to the <strong>Raksmart Client Portal</strong>.</li><li>Navigate to <strong>Product Management</strong> → <strong>Bare Metal Cloud</strong>.</li><li>Select the server you want to manage.</li><li>Open the <strong>Management</strong> page.</li><li>Click <strong>Reinstall OS</strong>.</li></ol><p>A configuration window will appear.</p><hr><h2 id="_3-configure-the-reinstallation-settings" tabindex="-1">3. Configure the Reinstallation Settings <a class="header-anchor" href="#_3-configure-the-reinstallation-settings" aria-label="Permalink to &quot;3. Configure the Reinstallation Settings&quot;">​</a></h2><h2 id="_1-select-the-operating-system" tabindex="-1">1. Select the Operating System <a class="header-anchor" href="#_1-select-the-operating-system" aria-label="Permalink to &quot;1. Select the Operating System&quot;">​</a></h2><p>Choose the operating system you want to install.</p><p>The available operating systems are determined by the options displayed in the control panel, such as:</p><ul><li>CentOS</li><li>Ubuntu</li><li>Debian</li><li>Windows Server</li></ul><hr><h2 id="_2-select-the-login-method" tabindex="-1">2. Select the Login Method <a class="header-anchor" href="#_2-select-the-login-method" aria-label="Permalink to &quot;2. Select the Login Method&quot;">​</a></h2><p>Two login methods are available.</p><h3 id="password-login" tabindex="-1">Password Login <a class="header-anchor" href="#password-login" aria-label="Permalink to &quot;Password Login&quot;">​</a></h3><p>When selecting <strong>Password Login</strong>, you can configure the server login password.</p><p>You may choose to:</p><ul><li>Use a randomly generated password provided by the system.</li><li>Set your own custom password.</li></ul><hr><h3 id="ssh-key-login" tabindex="-1">SSH Key Login <a class="header-anchor" href="#ssh-key-login" aria-label="Permalink to &quot;SSH Key Login&quot;">​</a></h3><p>Linux operating systems support SSH Key authentication.</p><p>When selecting <strong>SSH Key Login</strong>, choose an SSH public key from the list of keys already added to your account.</p><p>If you have not created an SSH public key yet, please add one first.</p><blockquote><p><strong>For more information, please refer to the <a href="/operations-knowledge-base/vps/ssh-public-key-management-guide.html"><em>SSH Public Key Management Guide</em></a>.</strong></p></blockquote><hr><h2 id="_3-configure-the-ssh-port" tabindex="-1">3. Configure the SSH Port <a class="header-anchor" href="#_3-configure-the-ssh-port" aria-label="Permalink to &quot;3. Configure the SSH Port&quot;">​</a></h2><p>For Linux systems, you may configure the SSH port.</p><p>You can choose to:</p><ul><li>Use a randomly generated port.</li><li>Specify a custom SSH port.</li></ul><blockquote><p><strong>Recommendation:</strong></p><p>If you change the default SSH port, make sure the corresponding port is allowed in both the security group and the operating system firewall. Otherwise, SSH connections may fail.</p></blockquote><hr><h2 id="_4-start-the-os-reinstallation" tabindex="-1">4. Start the OS Reinstallation <a class="header-anchor" href="#_4-start-the-os-reinstallation" aria-label="Permalink to &quot;4. Start the OS Reinstallation&quot;">​</a></h2><p>After confirming that all settings are correct, click <strong>Confirm</strong> to start the reinstallation.</p><p>The system will automatically perform the following operations:</p><ul><li>Format the system disk.</li><li>Install the selected operating system.</li><li>Configure the login method.</li><li>Configure the login password or SSH public key.</li><li>Configure the SSH port (Linux only).</li></ul><p>Once the installation is complete, you can log in using the newly configured credentials.</p><hr><h2 id="_5-disk-and-data-information" tabindex="-1">5. Disk and Data Information <a class="header-anchor" href="#_5-disk-and-data-information" aria-label="Permalink to &quot;5. Disk and Data Information&quot;">​</a></h2><h2 id="system-disk" tabindex="-1">System Disk <a class="header-anchor" href="#system-disk" aria-label="Permalink to &quot;System Disk&quot;">​</a></h2><p>During the OS reinstallation, the system disk will be formatted and a fresh operating system will be installed.</p><p>All data stored on the system disk will be erased.</p><hr><h2 id="data-disk" tabindex="-1">Data Disk <a class="header-anchor" href="#data-disk" aria-label="Permalink to &quot;Data Disk&quot;">​</a></h2><p>If the server has an additional data disk:</p><ul><li>The data disk will <strong>not</strong> be formatted during OS reinstallation.</li><li>Existing data on the data disk will be preserved.</li><li>The data disk will <strong>not</strong> be mounted automatically after the reinstallation.</li></ul><p>After logging into the server, manually mount the data disk before accessing the stored data.</p><hr><h2 id="disk-partition-information" tabindex="-1">Disk Partition Information <a class="header-anchor" href="#disk-partition-information" aria-label="Permalink to &quot;Disk Partition Information&quot;">​</a></h2><p>Disk partitions cannot be modified during the OS reinstallation process.</p><p>For servers with both a system disk and a data disk:</p><ul><li>The existing disk layout will remain unchanged.</li><li>The system disk and data disk cannot be merged.</li><li>If you need to redesign the disk layout, back up your data first and redeploy the server as needed.</li></ul><hr><h2 id="_6-additional-information" tabindex="-1">6. Additional Information <a class="header-anchor" href="#_6-additional-information" aria-label="Permalink to &quot;6. Additional Information&quot;">​</a></h2><h2 id="custom-script" tabindex="-1">Custom Script <a class="header-anchor" href="#custom-script" aria-label="Permalink to &quot;Custom Script&quot;">​</a></h2><p>If a <strong>Custom Script</strong> was configured when the instance was created:</p><ul><li>The same Custom Script will be executed automatically during the OS reinstallation.</li><li>Modifying or re-entering the Custom Script is not supported.</li></ul><hr><h2 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h2><p>After reinstalling the operating system:</p><ul><li>All existing snapshots of the instance will become invalid.</li><li>All snapshots will be deleted automatically.</li><li>Deleted snapshots cannot be recovered.</li></ul><p>If your snapshots contain important data, please back up the data before reinstalling the operating system.</p><hr><h2 id="_7-recommended-checks-after-reinstallation" tabindex="-1">7. Recommended Checks After Reinstallation <a class="header-anchor" href="#_7-recommended-checks-after-reinstallation" aria-label="Permalink to &quot;7. Recommended Checks After Reinstallation&quot;">​</a></h2><p>After the operating system has been installed, verify the following:</p><p>✅ You can successfully log in using the new login credentials.</p><p>✅ The correct operating system has been installed.</p><p>✅ SSH access is working properly (Linux).</p><p>✅ Remote Desktop (RDP) access is working properly (Windows).</p><p>✅ If the server has a data disk, it has been mounted successfully.</p><p>✅ Applications and services are functioning as expected.</p><hr><h2 id="_8-frequently-asked-questions" tabindex="-1">8. Frequently Asked Questions <a class="header-anchor" href="#_8-frequently-asked-questions" aria-label="Permalink to &quot;8. Frequently Asked Questions&quot;">​</a></h2><h3 id="q1-what-data-will-be-deleted-during-os-reinstallation" tabindex="-1">Q1: What data will be deleted during OS reinstallation? <a class="header-anchor" href="#q1-what-data-will-be-deleted-during-os-reinstallation" aria-label="Permalink to &quot;Q1: What data will be deleted during OS reinstallation?&quot;">​</a></h3><p>Only the <strong>system disk</strong> will be formatted.</p><p>If the server has an additional data disk, the data disk will not be formatted, and its data will remain intact.</p><hr><h3 id="q2-why-can-t-i-see-my-data-disk-after-the-reinstallation" tabindex="-1">Q2: Why can&#39;t I see my data disk after the reinstallation? <a class="header-anchor" href="#q2-why-can-t-i-see-my-data-disk-after-the-reinstallation" aria-label="Permalink to &quot;Q2: Why can&#39;t I see my data disk after the reinstallation?&quot;">​</a></h3><p>Your data disk has not been deleted.</p><p>After reinstalling the operating system, the data disk is <strong>not mounted automatically</strong>. You must manually mount the data disk before accessing its contents.</p><hr><h3 id="q3-can-i-set-my-own-login-password" tabindex="-1">Q3: Can I set my own login password? <a class="header-anchor" href="#q3-can-i-set-my-own-login-password" aria-label="Permalink to &quot;Q3: Can I set my own login password?&quot;">​</a></h3><p>Yes.</p><p>When using <strong>Password Login</strong>, you may either use the system-generated password or specify your own custom password.</p><hr><h3 id="q4-when-should-i-use-ssh-key-authentication" tabindex="-1">Q4: When should I use SSH Key authentication? <a class="header-anchor" href="#q4-when-should-i-use-ssh-key-authentication" aria-label="Permalink to &quot;Q4: When should I use SSH Key authentication?&quot;">​</a></h3><p>SSH Key authentication is recommended for Linux servers.</p><p>Compared with password authentication, SSH Keys provide stronger security and help protect against password leaks and brute-force attacks.</p><p>If you plan to use SSH Key authentication, please add an SSH public key to your account first.</p><hr><h3 id="q5-will-the-custom-script-be-executed-again-after-reinstalling-the-operating-system" tabindex="-1">Q5: Will the Custom Script be executed again after reinstalling the operating system? <a class="header-anchor" href="#q5-will-the-custom-script-be-executed-again-after-reinstalling-the-operating-system" aria-label="Permalink to &quot;Q5: Will the Custom Script be executed again after reinstalling the operating system?&quot;">​</a></h3><p>Yes.</p><p>The Custom Script configured when the instance was created will be executed automatically during the reinstallation process. It cannot be modified or replaced.</p><hr><h3 id="q6-can-snapshots-be-restored-after-reinstalling-the-operating-system" tabindex="-1">Q6: Can snapshots be restored after reinstalling the operating system? <a class="header-anchor" href="#q6-can-snapshots-be-restored-after-reinstalling-the-operating-system" aria-label="Permalink to &quot;Q6: Can snapshots be restored after reinstalling the operating system?&quot;">​</a></h3><p>No.</p><p>All existing snapshots will be automatically deleted during the OS reinstallation process and cannot be recovered.</p><hr><h3 id="q7-can-i-modify-the-disk-partitions-during-os-reinstallation" tabindex="-1">Q7: Can I modify the disk partitions during OS reinstallation? <a class="header-anchor" href="#q7-can-i-modify-the-disk-partitions-during-os-reinstallation" aria-label="Permalink to &quot;Q7: Can I modify the disk partitions during OS reinstallation?&quot;">​</a></h3><p>No.</p><p>Disk partitions cannot be modified during the reinstallation process. The existing system disk and data disk layout will remain unchanged and cannot be merged.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Back up all important data before reinstalling the operating system.</p><p>⚠️ Only the system disk is formatted during OS reinstallation. The data disk is preserved but must be mounted manually after the installation is complete.</p><p>⚠️ All existing snapshots of the instance will be automatically deleted during OS reinstallation and cannot be recovered.</p><p>⚠️ Disk partitions cannot be modified during the reinstallation process. The existing system disk and data disk layout will remain unchanged.</p><p>⚠️ If you change the SSH port, make sure the corresponding port is allowed by both the security group and the operating system firewall.</p><p>⚠️ The Custom Script configured when the instance was created will be executed automatically during the reinstallation process and cannot be modified.</p><hr>',115)])])}const g=t(o,[["render",s]]);export{c as __pageData,g as default};
